parameters.jsCode:
// Pecah naskah dari website menjadi 1 item per scene (dirender paralel di Fal.ai)
const raw = $input.first().json;
const data = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const scenes = Array.isArray(data.scenes) ? data.scenes : [];
if (!data.postId) throw new Error('postId tidak ada di payload website.');
if (scenes.length === 0) throw new Error('Payload tidak berisi scenes. Kirim ulang dari Meja Victor.');

const clipsCallback = data.clips_callback_url
  || String(data.callback_url || '').replace(/attach-video$/, 'attach-clips');
if (!/^https?:\/\//.test(clipsCallback)) throw new Error('clips_callback_url tidak valid: ' + clipsCallback);

return scenes
  .filter(s => (s.ai_video_prompt_en || '').trim())
  .map((s, i) => ({
    json: {
      postId: data.postId,
      scene_number: Number(s.scene_number) || i + 1,
      prompt: s.ai_video_prompt_en.trim(),
      overlay_text: s.overlay_text || '',
      fal_model: data.fal_model || 'fal-ai/kling-video/v2.5-turbo/pro/text-to-video',
      clip_duration: String(data.clip_duration || '5'),
      clips_callback_url: clipsCallback,
      access_code: data.access_code || ''
    }
  }));

// Gabungkan data scene dengan request_id antrian Fal.ai
const scenes = $('Parse Naskah & 5-Scene Prompts').all();
return $input.all().map((it, i) => ({
  json: {
    ...scenes[i].json,
    request_id: it.json.request_id,
    status_url: it.json.status_url,
    response_url: it.json.response_url,
    attempt: 0
  }
}));

// Cek apakah ke-5 klip sudah selesai. Semua item lewat bersamaan → mudah digabung.
const MAX_ATTEMPT = 20; // 20 x 60 detik = 20 menit
const prev = $('Tunggu 60 Detik').all();
const items = $input.all().map((it, i) => ({
  ...prev[i].json,
  fal_status: it.json.status,
  attempt: (prev[i].json.attempt || 0) + 1
}));
const allDone = items.every(x => x.fal_status === 'COMPLETED');
const timedOut = !allDone && items[0].attempt >= MAX_ATTEMPT;
return items.map(x => ({ json: { ...x, all_done: allDone, timed_out: timedOut } }));

// Susun 5 URL klip (urut scene) untuk dikirim ke website
const meta = $('Evaluasi Status').all();
const clips = $input.all().map((it, i) => ({
  scene_number: meta[i].json.scene_number,
  url: it.json.video?.url || it.json.video_url || ''
}));
const missing = clips.filter(c => !c.url);
if (missing.length) throw new Error('Fal.ai tidak mengembalikan URL video untuk scene: ' + missing.map(c => c.scene_number).join(', '));
const first = meta[0].json;
return [{ json: { postId: first.postId, clips, clips_callback_url: first.clips_callback_url, access_code: first.access_code } }];
